	defw VARPAR_I                   ; 028A  782d         -> bank 0: 2D78
LINSRH:
	rst 18H                         ; 028C  df           BANKJP
	defw LINSRH_I                   ; 028D  7a21         -> bank 0: 217A
AUTORUN:
	jp AUTORUN_T                    ; 028F  c31138       for ARUN
VARNAME:
	rst 18H                         ; 0292  df           BANKJP
	defw VARNAME_I                  ; 0293  252a         -> bank 0: 2A25
RUNSET:
	rst 18H                         ; 0295  df           BANKJP
	defw RUNSET_I                   ; 0296  601c         -> bank 0: 1C60
SUSING:
	rst 18H                         ; 0298  df           BANKJP
	defw SUSING_ENT                 ; 0299  6b00         -> bank 0: 006B
CMPTOK:
	rst 18H                         ; 029B  df           BANKJP
	defw CMPTOK_I                   ; 029C  3124         -> bank 0: 2431
USGCNT2:
	rst 18H                         ; 029E  df           BANKJP
	defw USGCNT                     ; 029F  5f00         -> bank 0: 005F
VARLET:
	rst 18H                         ; 02A1  df           BANKJP
	defw VARLET_I                   ; 02A2  342d         -> bank 0: 2D34
VARGET:
	rst 18H                         ; 02A4  df           BANKJP
	defw VARGET_I                   ; 02A5  b02b         -> bank 0: 2BB0
VARPEEK:
	rst 18H                         ; 02A7  df           BANKJP
	defw VARPEEK_I                  ; 02A8  3e2b         -> bank 0: 2B3E
POPDAT:
	rst 18H                         ; 02AA  df           BANKJP
	defw EVPOPDE                    ; 02AB  5f32         -> bank 0: 325F
VARLET2:
	rst 18H                         ; 02AD  df           BANKJP
	defw VARLET2_I                  ; 02AE  272c         -> bank 0: 2C27
VARPOKE:
	rst 18H                         ; 02B0  df           BANKJP
	defw VARPOKE_I                  ; 02B1  5a2b         -> bank 0: 2B5A
VARADR:
	rst 18H                         ; 02B3  df           BANKJP
	defw VARADR_I                   ; 02B4  d029         -> bank 0: 29D0
TOKSRH:
	rst 18H                         ; 02B6  df           BANKJP
	defw 8072H                      ; 02B7  7280         -> bank 6: 8072 T_TOKSRH
TOK2ASC:
	jp TOK2ASC_I                    ; 02B9  c37c12       token DE → ASCII (HL)
COMMADR:
	jp COMMADR_I                    ; 02BC  c32f11       token DE → jump address HL, bank-out → C, code → A
EXROMCOM:
	jp EXROMCOM_I                   ; 02BF  c31a11       as 02BCH, but ROM-bit only (F1BFH)
EXROMBANK:
	jp EXROMBANK_I                  ; 02C2  c3f311       bank-select the ROM module in C
LINSRH2:
	jp LINSRH2_I                    ; 02C5  c32513       find line BC from address DE
LINSRHREL:
	jp LINSRHREL_I                  ; 02C8  c3e112       find line BC relative from address (F89CH) — e.g. for GOTO
EXCOMMEXE:
	jp EXCOMMEXE_I                  ; 02CB  c3a815       execute the command token (F35FH) of a ROM module
LABSCH:
	jp LABSCH_I                     ; 02CE  c33914       find label (HL), length BC, in all slots
LBSCH2:
	jp LBSCH2_I                     ; 02D1  c36a13       as 02CEH, but only in the slot currently selected via TITLE
TADCNV:
	jp TADCNV_I                     ; 02D4  c32915       bank-select logical bank C
LOGADR:
	jp LOGADR_I                     ; 02D7  c35315       convert logical address DE → physical address, BC, bank-out → A
LOGEND:
	jp LOGEND_I                     ; 02DA  c37c15       logical address of the BASIC program end → DE

; 02DDH is only 2 bytes: LD C,3 falls into EXROMWK
EXROM3WK:
	ld c,03H                        ; 02DD  0e03         C = 3 (ROM module 3) ...
EXROMWK:
	jp EXROMWK_I                    ; 02DF  c39d1a       allocate DE bytes of work area for ROM module C -> HL
DIRCOMEXE:
	jp DIRCOMEXE_I                  ; 02E2  c3cd39       execute a direct-command token DE, processing pointer HL
PRGEXE:
	jp STMTTOKEN                    ; 02E5  c3753b       run the program from (FE00H), after calling 02BCH
INPUT1:
	jp INPUT1_T                     ; 02E8  c32338       the INPUT statement (P1-B0 5E6BH)
NXTADR:
	jp PRINT_T                      ; 02EB  c31d38       the PRINT statement (P1-B0 6333H; Systemhandbuch: "INPUT1 (NXTADR) for PRINT")
UNDOC02EE:
	rst 18H                         ; 02EE  df           BANKJP
	defw CALLB3B_40BD               ; 02EF  ba38         -> bank 0: 38BA
PASWPTST:
	rst 18H                         ; 02F1  df           BANKJP
	defw PASWPTST_I                 ; 02F2  811e         -> bank 0: 1E81
PRGADR:
	rst 18H                         ; 02F4  df           BANKJP
	defw PRGADR_I                   ; 02F5  8b18         -> bank 0: 188B
EXROMCOMC:
	jp NEXTTOKT                     ; 02F7  c33612       find the same token in another ROM module
RAMODSET:
	jp RAMODSET_I                   ; 02FA  c33f16       set the system addresses of the RAM modules, A = mode (00/01)
ALLOFF2:
	jp ALLOFF2_I                    ; 02FD  c37e17       plotter motors off
LPRTASTR2:
	jp LPRTASTR2_I                  ; 0300  c36617       LPRINT B* (HL)
BINBCD:
	rst 18H                         ; 0303  df           BANKJP
	defw INT2BCDHL                  ; 0304  0419         -> bank 0: 1904
EOF2:
	rst 18H                         ; 0306  df           BANKJP
	defw CALLB3B_4015               ; 0307  cf38         -> bank 0: 38CF
JAPAN0309:
	rst 18H                         ; 0309  df           BANKJP
	defw JAPANSVC+8000H             ; 030A  90fc         -> bank 0: 7C90 (via C000H alias)
EDRESET:
	rst 18H                         ; 030C  df           BANKJP
	defw EDRESET_I+8000H            ; 030D  04f5         -> bank 0: 7504 (via C000H alias)
PRTWAITK:
	rst 18H                         ; 030F  df           BANKJP
	defw PRTWAITK_I+8000H           ; 0310  39fd         -> bank 0: 7D39 (via C000H alias)
BASPARES:
	rst 18H                         ; 0312  df           BANKJP
	defw BASPARES_I                 ; 0313  791c         -> bank 0: 1C79

; Four extra entries used only by the reset routine (NEW ROM revision); they
; lead via the bank-3 jump table at 40E1H-40EAH to 6BAFH/6BD0H/6BF0H/6C0BH.
RSTEXT1:
	rst 18H                         ; 0315  df           BANKJP
	defw 40E1H                      ; 0316  e140         -> bank 3: 40E1 T_RSTEXT1
RSTEXT2:
	rst 18H                         ; 0318  df           BANKJP
	defw 40E4H                      ; 0319  e440         -> bank 3: 40E4 T_RSTEXT2
RSTEXT3:
	rst 18H                         ; 031B  df           BANKJP
	defw 40E7H                      ; 031C  e740         -> bank 3: 40E7 T_RSTEXT3
RSTEXT4:
	rst 18H                         ; 031E  df           BANKJP
	defw 40EAH                      ; 031F  ea40         -> bank 3: 40EA T_RSTEXT4

; IM2 interrupt vector: I = 03H, port 39H = 21H, so the vector word is at 0321H,
; immediately below the reset code it follows (TRM: vector = entry address - 2).
IM2VEC:
	defw INTHND                     ; 0321  2c08         IM2 vector table (I=03H, port 39H=21H) -> interrupt handler



; ============================================================================
; RESET / POWER-ON
; ============================================================================

;------------------------------------------------------------------------------
; 0323H - Reset / power-on entry (from 0002H)
; Every power-on is a Z-80 reset (the sub-CPU holds RSTIN# low for 30 ms).
; 1. LCD clock on, SP = FA38H, LCD display off, settle, init the TC8576 CPC.
; 2. Ask the sub-CPU for the reset cause (timer IOCS 15H), re-order its bits
;    into RSTCAUSE (FA1BH): b0 ALL RESET, b1 RESET switch, b2 external reset,
;    b4 ON key, b5 external power-on, b6 WAKE$(0), b7 WAKE$(1).
; 3. For a power-on, an A5H x4 signature at ZZ (FA08H) means "auto power-off,
;    resume": SP is reloaded from SAVESP and the handler at APONBK/APONAD
;    (default bank 3, 407EH) is called; on success execution continues in the
;    auto-power-off routine at 0BBDH, i.e. the program resumes.
; 4. Otherwise a normal start: IM 2, work-area init (ALL RESET: full clear),
;    slot/module detection, CPU hand-shake with the LH-5803, ROM module scan,
;    calls into every module, timer/COM init, and finally the boot search which
;    ends in the boot vector BOOTBK/BOOTAD (default 0C04H, BASIC).
;------------------------------------------------------------------------------
RESETGO:
	ld a,10H                        ; 0323  3e10         b4 = LCD processor clock (CK0) on
	out (P_CGC),a                   ; 0325  d337
	ld sp,BASSTK                    ; 0327  3138fa
	ld a,3EH                        ; 032A  3e3e         HD61202 command 3EH = display OFF
	call LCDWAIT                    ; 032C  cd0608
	out (P_LCD1C),a                 ; 032F  d350
	call DELAY30K                   ; 0331  cd6c07
	call CPCINIT                    ; 0334  cd8c07
	call WAITONUP                   ; 0337  cd7507
	ld hl,SYSFLG                    ; 033A  21b8f0
	res 0,(hl)                      ; 033D  cb86         sub-CPU commands paced to 64 Hz until probed
	ld a,04H                        ; 033F  3e04         04H: bank 3 = normal ROM, not the hidden 3b
	ld (PORT3D_M),a                 ; 0341  327df0
	out (P_ROMSEL),a                ; 0344  d33d
	ld c,15H                        ; 0346  0e15         timer IOCS 15H: reset / power-on cause -> A
	call TIMER                      ; 0348  cdd501

; Reorder the cause bits: answer b7..b5 -> C b2..b0 (b5 ALL RESET -> b0),
; answer b4 dropped, answer b3..b0 -> C b4..b7.
	ld c,00H                        ; 034B  0e00
	ld b,03H                        ; 034D  0603
L034F:
	rlca                            ; 034F  07
	rr c                            ; 0350  cb19
	djnz L034F                      ; 0352  10fb
	rlca                            ; 0354  07
	ld b,04H                        ; 0355  0604
L0357:
	rlca                            ; 0357  07
	rr c                            ; 0358  cb19
	djnz L0357                      ; 035A  10fb
	ld a,c                          ; 035C  79
	bit 3,a                         ; 035D  cb5f
	jr z,L0363                      ; 035F  2802
	ld a,01H                        ; 0361  3e01         ALL RESET: RSTCAUSE = 01H exactly
L0363:
	and a                           ; 0363  a7
	jr nz,RSTSAVE                   ; 0364  2002
	ld a,10H                        ; 0366  3e10         no cause bits: treat as ON-key power-on (10H)



;------------------------------------------------------------------------------
; 0368H - Store the start cause in A and continue the boot
; Also entered from the power-off code.
;------------------------------------------------------------------------------
RSTSAVE:
	ld (RSTCAUSE),a                 ; 0368  321bfa
	cp 10H                          ; 036B  fe10         < 10H: a reset, not a power-on
	jr c,L0374                      ; 036D  3805
	call SIGCHK                     ; 036F  cde607
	jr c,L037D                      ; 0372  3809         signature found: resume with the saved stack
L0374:
	call SIGCLR                     ; 0374  cdfe07
	ld hl,0F5FFH                    ; 0377  21fff5
	ld (SAVESP),hl                  ; 037A  22daf0
L037D:
	ld sp,(SAVESP)                  ; 037D  ed7bdaf0     SP = saved (resume) or F5FFH (normal start)

; Interrupt mode 2, vector table at 0321H (I = 03H, port 39H = 21H).
	ld hl,0321H                     ; 0381  212103
	ld a,h                          ; 0384  7c
	ld i,a                          ; 0385  ed47
	ld a,l                          ; 0387  7d
	out (P_IVEC),a                  ; 0388  d339
	im 2                            ; 038A  ed5e
	call DELAY30K                   ; 038C  cd6c07
	call CPCINIT                    ; 038F  cd8c07
	ld hl,SYSFLG                    ; 0392  21b8f0
	res 0,(hl)                      ; 0395  cb86
	ld hl,0FA21H                    ; 0397  2121fa       clear FA21H-FA24H (flags collected during boot)
	xor a                           ; 039A  af
	ld b,04H                        ; 039B  0604
L039D:
	ld (hl),a                       ; 039D  77
	inc hl                          ; 039E  23
	djnz L039D                      ; 039F  10fc
	call WAITONUP                   ; 03A1  cd7507
	ld a,(RSTCAUSE)                 ; 03A4  3a1bfa
	cp 10H                          ; 03A7  fe10
	jr nc,L03B7                     ; 03A9  300c         power-on (>= 10H): keep the work area
	cp 02H                          ; 03AB  fe02
	jr nc,L03B4                     ; 03AD  3005         RESET switch / external reset: vectors only
	call ALLRESET                   ; 03AF  cddd06       ALL RESET: clear the whole work area
	jr L03B7                        ; 03B2  1803
L03B4:
	call VECINIT                    ; 03B4  cd2e07
L03B7:
	ld c,25H                        ; 03B7  0e25         timer IOCS 25H: does the sub-CPU need 64 Hz pacing?
	call TIMER                      ; 03B9  cdd501
	ld hl,SYSFLG                    ; 03BC  21b8f0       -> SYSFLG b0 (1 = send commands unpaced)
	or (hl)                         ; 03BF  b6
	ld (hl),a                       ; 03C0  77

; LCD display start line = DSPLPTR, as HD61202 command C0H+line*8.
	ld a,(DSPLPTR)                  ; 03C1  3a5cf0
	add a,a                         ; 03C4  87
	add a,a                         ; 03C5  87
	add a,a                         ; 03C6  87
	or 0C0H                         ; 03C7  f6c0
	call LCDWAIT                    ; 03C9  cd0608
	out (P_LCD1C),a                 ; 03CC  d350
	xor a                           ; 03CE  af
	out (P_SLOT),a                  ; 03CF  d33c

; Probe the Slot 1 memory window (SLOTMAP = 0 meanwhile) to decide SLOTMAP:
; RAM/ROM at bank 0 B000H -> 1BH, else at A800H -> 1AH, else 5BH.
	ld d,00H                        ; 03D1  1600
	ld e,0B0H                       ; 03D3  1eb0
	call MEMORYCHK_I                ; 03D5  cd1f09
	jr c,L03E9                      ; 03D8  380f
	ld e,0A8H                       ; 03DA  1ea8
	call MEMORYCHK_I                ; 03DC  cd1f09
	jr c,L03E5                      ; 03DF  3804
	ld a,5BH                        ; 03E1  3e5b
	jr L03EB                        ; 03E3  1806
L03E5:
	ld a,1AH                        ; 03E5  3e1a
	jr L03EB                        ; 03E7  1802
L03E9:
	ld a,1BH                        ; 03E9  3e1b
L03EB:
	ld (SLOTMAPM),a                 ; 03EB  328df0
	out (P_SLOT),a                  ; 03EE  d33c

; Detect whether a Slot-2 I/O device answers at ports 60H-67H: save the 8
; values, write 05H..0CH, read back.  If all read back, restore them and flag
; FA24H.7 (device present => module configuration changed: signature cleared).
	ld bc,8060H                     ; 03F0  016080       B = 80H is on A8-A15 during IN (C); C = port 60H
	ld d,08H                        ; 03F3  1608
L03F5:
	in a,(c)                        ; 03F5  ed78
	push af                         ; 03F7  f5
	inc bc                          ; 03F8  03
	dec d                           ; 03F9  15
	jr nz,L03F5                     ; 03FA  20f9
	ld c,60H                        ; 03FC  0e60
	ld d,08H                        ; 03FE  1608
	ld a,05H                        ; 0400  3e05
L0402:
	out (c),a                       ; 0402  ed79
	inc bc                          ; 0404  03
	inc a                           ; 0405  3c
	dec d                           ; 0406  15
	jr nz,L0402                     ; 0407  20f9
	ld c,60H                        ; 0409  0e60
	ld d,08H                        ; 040B  1608
	ld e,05H                        ; 040D  1e05
L040F:
	in a,(c)                        ; 040F  ed78
	cp e                            ; 0411  bb
	jr nz,L042E                     ; 0412  201a
	inc bc                          ; 0414  03
	inc e                           ; 0415  1c
	dec d                           ; 0416  15
	jr nz,L040F                     ; 0417  20f6
	ld c,67H                        ; 0419  0e67
	ld d,08H                        ; 041B  1608
L041D:
	pop af                          ; 041D  f1
	out (c),a                       ; 041E  ed79
	dec bc                          ; 0420  0b
	dec d                           ; 0421  15
	jr nz,L041D                     ; 0422  20f9
	call SIGCLR                     ; 0424  cdfe07
	ld hl,0FA24H                    ; 0427  2124fa
	set 7,(hl)                      ; 042A  cbfe
	jr L0433                        ; 042C  1805
L042E:
	ld b,08H                        ; 042E  0608         no device: drop the 8 saved values
L0430:
	pop af                          ; 0430  f1
	djnz L0430                      ; 0431  10fd

; Remember the old module bitmaps (F0AE-F0B1H) in YY to detect configuration changes.
L0433:
	ld hl,(ROM4MAP)                 ; 0433  2aaef0
	ld (YY),hl                      ; 0436  2210fa
	ld hl,(0F0B0H)                  ; 0439  2ab0f0
	ld (0FA12H),hl                  ; 043C  2212fa
	ld a,08H                        ; 043F  3e08         interrupt mask: only b3 (LH-5803) enabled
	out (P_ZMSK),a                  ; 0441  d335
	ld a,40H                        ; 0443  3e40         LH-5803 call mode 40H: initialise the LH-5803 side
	ld (LHMODE),a                   ; 0445  3202f0
	call CALLH                      ; 0448  cdc601       the LH-5803 enables interrupts again on return
	di                              ; 044B  f3
	ld a,04H                        ; 044C  3e04
	ld (PORT3D_M),a                 ; 044E  327df0
	out (P_ROMSEL),a                ; 0451  d33d

; Scan banks 1-7 for ROM modules (ID 43H,16H) at 4000H and at 6000H.
	ld hl,4000H                     ; 0453  210040
	call SCANMODS                   ; 0456  cdc507
	ld (ROM4MAP),a                  ; 0459  32aef0
	ld hl,6000H                     ; 045C  210060
	call SCANMODS                   ; 045F  cdc507
	ld (ROM6MAP),a                  ; 0462  32aff0
	ld a,07H                        ; 0465  3e07         module function 7: reset
	ld l,02H                        ; 0467  2e02
	ld de,(ROM4MAP)                 ; 0469  ed5baef0
	call CALLMODS                   ; 046D  cd5108
	ld hl,(ROM4MAP)                 ; 0470  2aaef0
	ex de,hl                        ; 0473  eb
	ld hl,(YY)                      ; 0474  2a10fa       bitmaps changed: clear the signature
	and a                           ; 0477  a7
	sbc hl,de                       ; 0478  ed52
	call nz,SIGCLR                  ; 047A  c4fe07
	ld hl,(0F0B0H)                  ; 047D  2ab0f0
	ex de,hl                        ; 0480  eb
	ld hl,(0FA12H)                  ; 0481  2a12fa
	and a                           ; 0484  a7
	sbc hl,de                       ; 0485  ed52
	call nz,SIGCLR                  ; 0487  c4fe07
	ld c,01H                        ; 048A  0e01
	ld a,(ROM4MAP)                  ; 048C  3aaef0
	call RSTEXT3                    ; 048F  cd1b03       bank 3 6BF0H: register the modules of the 4000H map
	ld a,(ROM6MAP)                  ; 0492  3aaff0
	call RSTEXT3                    ; 0495  cd1b03       ... and of the 6000H map
	ld hl,(MODCFG1)                 ; 0498  2a23f1
	ld (YY),hl                      ; 049B  2210fa
	ld hl,(MODCFG2)                 ; 049E  2a25f1
	ld (0FA12H),hl                  ; 04A1  2212fa
	call RSTEXT4                    ; 04A4  cd1e03       bank 3 6C0BH: rebuild the coded configuration
	ld hl,(YY)                      ; 04A7  2a10fa
	ld de,(MODCFG1)                 ; 04AA  ed5b23f1
	call RSTEXT2                    ; 04AE  cd1803       bank 3 6BD0H: compare with the old one (flags a change)
	ld hl,(0FA12H)                  ; 04B1  2a12fa
	ld de,(MODCFG2)                 ; 04B4  ed5b25f1
	call RSTEXT2                    ; 04B8  cd1803

; Check for a JAPAN ROM (header 'M',3xH/4xH at bank 4, 8000H) -> D.0
	ld d,00H                        ; 04BB  1600
	call SELJROM                    ; 04BD  cd7e07
	ld a,(8000H)                    ; 04C0  3a0080
	cp 4DH                          ; 04C3  fe4d
	jr nz,L04E5                     ; 04C5  201e
	ld a,(8001H)                    ; 04C7  3a0180
	and 0F0H                        ; 04CA  e6f0
	cp 30H                          ; 04CC  fe30
	jr z,L04D4                      ; 04CE  2804
	cp 40H                          ; 04D0  fe40
	jr nz,L04E5                     ; 04D2  2011
L04D4:
	set 0,d                         ; 04D4  cbc2
	jr L04E5                        ; 04D6  180d



;------------------------------------------------------------------------------
; 04D8H - (01C9H) Switch the power off through the LH-5803
; Entry of POFF / PAOFF.  Waits a moment (SWAIT, BC = 2), then hands over to
; the LH-5803 OFF routine in bank 3 at 4042H.
;
;   Entry parameters: A = 3 for the OFF key, 4 for auto power-off
; Modified registers: Does not return on a real unit
;   Error conditions: None
;------------------------------------------------------------------------------
PWROFF:
	ld bc,0002H                     ; 04D8  010200
	call SWAIT                      ; 04DB  cdba01
	rst 18H                         ; 04DE  df           BANKJP bank 3 4042H: LH-5803 OFF routine
	defw 4042H                      ; 04DF  4240         -> bank 3: 4042 T_PWROFF
	defb 00H,00H,00H,00H            ; 04E1  00000000     unused

; F122H b0 = JAPAN ROM present; a change also invalidates the resume signature.
L04E5:
	ld a,(MODCFG)                   ; 04E5  3a22f1
	and 03H                         ; 04E8  e603
	cp d                            ; 04EA  ba
	call nz,SIGCLR                  ; 04EB  c4fe07
	ld a,(MODCFG)                   ; 04EE  3a22f1
	and 0FCH                        ; 04F1  e6fc
	or d                            ; 04F3  b2
	ld (MODCFG),a                   ; 04F4  3222f1
	ld a,04H                        ; 04F7  3e04
	ld (PORT3D_M),a                 ; 04F9  327df0
	out (P_ROMSEL),a                ; 04FC  d33d
	xor a                           ; 04FE  af
	out (P_SUBDAT),a                ; 04FF  d333
	ld (TMRMSK),a                   ; 0501  327ef0
	ld c,12H                        ; 0504  0e12         timer IOCS 12H SRIRQ: read (and so clear) pending events
	call TIMER                      ; 0506  cdd501
	xor a                           ; 0509  af
	out (P_CL1),a                   ; 050A  d336
	ld (BINTP1),a                   ; 050C  32d3f1
	ld (BINTP2),a                   ; 050F  32d4f1
	ld hl,BMODE                     ; 0512  21bcf1
	ld a,(hl)                       ; 0515  7e
	and 7FH                         ; 0516  e67f
	ld b,a                          ; 0518  47
	in a,(P_OPB)                    ; 0519  db1f         PB3 -> BMODE b7
	and 08H                         ; 051B  e608
	jr z,L0521                      ; 051D  2802
	set 7,b                         ; 051F  cbf8
L0521:
	ld (hl),b                       ; 0521  70
	ld hl,KEYWK2                    ; 0522  217af0
	res 0,(hl)                      ; 0525  cb86
	ld hl,0000H                     ; 0527  210000
	ld (CONTADR),hl                 ; 052A  22b9f0
	call SIGCHK                     ; 052D  cde607       resume after auto power-off?
	jr nc,L0570                     ; 0530  303e

; Resume after auto power-off: re-initialise the peripherals with "power on
; after APO" (A = 2), then call the APO handler (default bank 3 407EH).  Any
; configuration change flagged in FA21H-FA24H forces a normal start instead.
	call BUZON                      ; 0532  cdc301
	ld a,02H                        ; 0535  3e02
	ld c,00H                        ; 0537  0e00         timer IOCS 00H SINIT
	call TIMER                      ; 0539  cdd501
	ld a,02H                        ; 053C  3e02
	ld c,00H                        ; 053E  0e00
	call COM                        ; 0540  cdd801       COM IOCS 00H init
	ld a,02H                        ; 0543  3e02
	ld de,(ROM4MAP)                 ; 0545  ed5baef0
	ld l,02H                        ; 0549  2e02
