	push hl                         ; 0A93  e5
	push af                         ; 0A94  f5
	push de                         ; 0A95  d5
	ld hl,0009H                     ; 0A96  210900       SP+9 -> high byte of the operand pointer
	add hl,sp                       ; 0A99  39
	ld d,(hl)                       ; 0A9A  56           operand pointer high := old port 3DH
	ld a,(PORT3D_M)                 ; 0A9B  3a7df0
	ld (hl),a                       ; 0A9E  77
	ld a,04H                        ; 0A9F  3e04
	ld (PORT3D_M),a                 ; 0AA1  327df0
	out (P_ROMSEL),a                ; 0AA4  d33d
	dec hl                          ; 0AA6  2b
	ld e,(hl)                       ; 0AA7  5e           operand pointer low := old port 31H
	in a,(P_BANK)                   ; 0AA8  db31
	ld (hl),a                       ; 0AAA  77
	dec hl                          ; 0AAB  2b
	ld (hl),0AH                     ; 0AAC  360a         plant BJPRET (0AE4H) as return address
	dec hl                          ; 0AAE  2b
	ld (hl),0E4H                    ; 0AAF  36e4
	ex de,hl                        ; 0AB1  eb
	ld e,(hl)                       ; 0AB2  5e
	inc hl                          ; 0AB3  23
	ld d,(hl)                       ; 0AB4  56
	ex de,hl                        ; 0AB5  eb
	ld a,h                          ; 0AB6  7c
	add a,a                         ; 0AB7  87
	jr c,L0AC4                      ; 0AB8  380a
	jp m,L0AD8                      ; 0ABA  fad80a
	in a,(P_BANK)                   ; 0ABD  db31
