	exx                             ; 0B5B  d9
	ex af,af'                       ; 0B5C  08
	pop iy                          ; 0B5D  fde1
	pop ix                          ; 0B5F  dde1
	pop hl                          ; 0B61  e1
	pop de                          ; 0B62  d1
	pop bc                          ; 0B63  c1
	pop af                          ; 0B64  f1
