; ============================================================================
; BASIC BOOT
; ============================================================================

;------------------------------------------------------------------------------
; 0C04H - Default boot vector: BASIC cold / warm start
; BOOTBK/BOOTAD = bank 0, 0C04H; entered by BANKJUMP from the reset code.
; Resets the display, installs the default APO handler and user interrupt
; hooks, re-checks the memory configuration and then either
;  - prints "NEW0? :CHECK xx" if the configuration changed / problems were
;    flagged in FA21H-FA24H during reset, or
;  - (WAKE$ power-on) types WAKE$(0) / WAKE$(1) into the key buffer, or
;  - (AUTO RUN) finds AUTORUN.BAS on a device or an ARUN program, or
;  - just enters BASIC command mode (RESCA).
;
;   Entry parameters: A = start cause (RSTCAUSE)
; Modified registers: Does not return
;   Error conditions: None
;------------------------------------------------------------------------------
BASBOOT:
	push af                         ; 0C04  f5
	cp 01H                          ; 0C05  fe01
	jr nz,L0C0E                     ; 0C07  2005
	ld hl,TITLE                     ; 0C09  21d5f1       ALL RESET: TITLE := S0
	ld (hl),00H                     ; 0C0C  3600
L0C0E:
	cp 10H                          ; 0C0E  fe10         a reset (not a power-on): default status symbols
	call c,SYMDEFLT                 ; 0C10  dc740f
	pop af                          ; 0C13  f1
	push af                         ; 0C14  f5
	call EDRESET                    ; 0C15  cd0c03
	ld de,0000H                     ; 0C18  110000
	call CRSRSET                    ; 0C1B  cd1501
