	call LWIDTH                     ; 0C1F  cd0f01
	call CLS                        ; 0C22  cd1201
	ld a,01H                        ; 0C25  3e01
	call BSPCTR                     ; 0C27  cde500
	ld a,03H                        ; 0C2A  3e03         default auto-power-on handler: bank 3, 407EH
	ld hl,407EH                     ; 0C2C  217e40
	ld (APONBK),a                   ; 0C2F  32cbf0
	ld (APONAD),hl                  ; 0C32  22ccf0

; Default user hooks for the three sub-CPU timers: bank byte C0H (b7=b6=1: armed,
; bank 0) and the handlers UIWAKE/UITIME/UIALARM which just flag BINTREQ.
	ld a,0C0H                       ; 0C35  3ec0
	ld hl,UIWAKE                    ; 0C37  21b70f
	ld (0F0C9H),hl                  ; 0C3A  22c9f0
	ld (UHWAKE),a                   ; 0C3D  32c8f0
	ld hl,UITIME                    ; 0C40  21bd0f
	ld (UHALM1),a                   ; 0C43  32c2f0
	ld (0F0C3H),hl                  ; 0C46  22c3f0
	ld hl,UIALARM                   ; 0C49  21c30f
	ld (UHALM2),a                   ; 0C4C  32c5f0
