	cp 0C4H                         ; 3FAE  fec4
	jr c,KEYDEFEND                  ; 3FB0  38f7
	ld l,0C4H                       ; 3FB2  2ec4
	ret                             ; 3FB4  c9



;------------------------------------------------------------------------------
; 3FB5H - ON KEY / label jump (ext)
; Tokenizes the input line (P1-B0 7D4CH) or uses an empty one, then searches
; the label named by the key code (A) with LABSCH.  The routine runs on into
; P1-B0 at 4000H: the two 16 KB halves of bank 0 are one contiguous program.
; DEF-key execution: this is how DEF + key runs the program at label "k"; the
; continuation in P1-B0 enters AREAD first when the labelled line starts with it.
;------------------------------------------------------------------------------
KEYLABEL:
	ld hl,0000H                     ; 3FB5  210000
	ld (0FE0AH),hl                  ; 3FB8  220afe
	push bc                         ; 3FBB  c5
	ld a,(EDFLG)                    ; 3FBC  3a80f8
	bit 6,a                         ; 3FBF  cb77
	jr z,L3FDB                      ; 3FC1  2818
	call DELINSMARKS                ; 3FC3  cde27c
	ld a,(EDLIM)                    ; 3FC6  3a13fe
	call INBPTR                     ; 3FC9  cdc045
	ld de,LISTBUF                   ; 3FCC  11b0fb
	ld hl,INBUF                     ; 3FCF  211df2
	call TOKENIZE_I                 ; 3FD2  cd4c7d
	ld (PROCPTR),de                 ; 3FD5  ed5300fe
	jr L3FE4                        ; 3FD9  1809
L3FDB:
	ld hl,LISTBUF                   ; 3FDB  21b0fb
	ld a,0DH                        ; 3FDE  3e0d
	ld (hl),a                       ; 3FE0  77
	ld (PROCPTR),hl                 ; 3FE1  2200fe
L3FE4:
	pop af                          ; 3FE4  f1
	ld hl,UU                        ; 3FE5  2118fa
	ld (hl),a                       ; 3FE8  77
	xor a                           ; 3FE9  af
	ld (0FA19H),a                   ; 3FEA  3219fa
	ld bc,0001H                     ; 3FED  010100
	push hl                         ; 3FF0  e5
	call LABSCH                     ; 3FF1  cdce02
	pop hl                          ; 3FF4  e1
	jr nc,L3FFC                     ; 3FF5  3005
	ld a,0BH                        ; 3FF7  3e0b         error 0BH: label not found
	jp DIRERROR                     ; 3FF9  c3723a
L3FFC:
	ld de,(SRCHADR)                 ; 3FFC  ed5ba6f8     continued at 4000H (P1-B0)

	end
